python
def weightedLinesPositiveProofStrip(links, k):
    a=links
    out=[]
    import heapq
    n=len(a)
    dist=[float('inf')]*n
    heap=[]
    if n:
        dist[0]=0
        heap=[(0,0)]
    while heap:
        cost,u=heapq.heappop(heap)
        if cost!=dist[u]: continue
        for v in range(n):
            if a[u][v]>0 and cost+a[u][v]<dist[v]:
                dist[v]=cost+a[u][v]
                heapq.heappush(heap,(dist[v],v))
    out=[d if d!=float('inf') else -1 for d in dist]
    return [x for x in out if x>0]


java
class Solution {
  public int[] weightedLinesPositiveProofStrip(int[][] links, int k) {
    int[][] a=links; List<Integer> out=new ArrayList<>();
    {int n=a.length;int[]dist=new int[n];Arrays.fill(dist,Integer.MAX_VALUE);PriorityQueue<int[]>heap=new PriorityQueue<>(Comparator.comparingInt(x->x[0]));if(n>0){dist[0]=0;heap.add(new int[]{0,0});}while(!heap.isEmpty()){int[]entry=heap.remove();int cost=entry[0],u=entry[1];if(cost!=dist[u])continue;for(int v=0;v<n;v++)if(a[u][v]>0&&cost+a[u][v]<dist[v]){dist[v]=cost+a[u][v];heap.add(new int[]{dist[v],v});}}for(int d:dist)out.add(d==Integer.MAX_VALUE?-1:d);}
    return out.stream().filter(x->x>0).mapToInt(Integer::intValue).toArray();
  }
}
